  "nivel": "Intermedio",
  "equipo": "Colchoneta",
  "musculos": [
   "Recto abdominal",
   "Oblicuos"
  ],
  "para": "Trabaja el abdomen con mínima carga sobre la columna. Se utiliza en programas de resistencia del core en dolor lumbar.",
