  "errores": [
   "Inclinar el tronco hacia el lado de la carga",
   "Elevar el hombro hacia la oreja",
   "Ir demasiado rápido"
  ],
  "precauciones": [
   "Elegir un peso que permita mantener la postura",
   "Detener ante dolor lumbar o de hombro"
  ],
  "escena": "Persona caminando por un pasillo con una pesa ligera en una mano a un costado del cuerpo, otra mano libre. Tronco erguido y hombros nivelados durante todo el recorrido.",
