   "Con una mano tira ligeramente hacia adelante y hacia arriba de un extremo de la toalla, como un empuje suave sobre la vértebra, sin presionar la garganta.",
   "Exhala y gira lentamente la cabeza hacia el lado limitado, manteniendo la mirada al frente en el horizonte y sin dolor.",
   "Mantén 2 segundos al final del giro, vuelve al centro mientras inhalas y suelta la toalla.",
