  "escena": "Persona sentada erguida con una toalla pequeña alrededor de la base del cuello; una mano sostiene un extremo y tira suavemente hacia adelante. Desde esa posición gira la cabeza con calma hacia un lado, con la mirada al frente, y regresa al centro.",
